 * @param {string} root
 * @param {string[]} [dirs]
 * @returns {Array<{ path: string, content: string }>}
 */
export function readSpecFiles(root, dirs = ["specs", "adrs"]) {
    return dirs
        .map((dir) => path.join(root, dir))
        .filter((base) => fs.existsSync(base))
        .flatMap((base) => readMarkdownUnder(root, base));
}

